const NOV_VER='2026-09-01.1';   // marca da última leva de novidades (reacende o indicador quando muda)
function abreNovidades(){
  try{ localStorage.setItem('jirainsight_nov_visto', NOV_VER); }catch(e){}
  const dot=document.getElementById('nov-dot'); if(dot) dot.hidden=true;
  const md=document.getElementById('mais-dot'); if(md) md.hidden=true;
  abreModal(`<h2>✨ Novidades</h2>
    <div class="muted small">O que há de novo no painel — o histórico completo fica no manual.</div>
    <div class="nov-lista">${NOVIDADES.map(([d,txt])=>`<div class="nov-item">
      <span class="nov-data">${esc(d)}</span><span class="nov-txt">${txt}</span></div>`).join('')}</div>`);
}
function marcaNovidade(){
  let visto=''; try{ visto=localStorage.getItem('jirainsight_nov_visto')||''; }catch(e){}
  const dot=document.getElementById('nov-dot'); if(dot) dot.hidden = (visto===NOV_VER);
  const md=document.getElementById('mais-dot'); if(md) md.hidden = (visto===NOV_VER);
}
// "Ver todas as novidades" do card da tela inicial: abre o modal (marca como visto)
// e re-renderiza a inicial para o destaque do card apagar.
document.getElementById('conteudo').addEventListener('click',(e)=>{
  if(!(e.target.closest&&e.target.closest('[data-nov-todas]'))) return;
  abreNovidades();
  if(estado.vista==='acoes') renderAcoes();
});
